import{_ as c}from"./chunks/ArticleMetadata.Xa7L4Afm.js";import{_ as l,D as s,o as r,c as p,I as d,w as u,k as i,a as m,R as h,b as _,e as f}from"./chunks/framework.Dn7lIAzt.js";import"./chunks/md5.vgHT5zCM.js";const P=JSON.parse('{"title":"启动链路","description":"","frontmatter":{"title":"启动链路","author":"阿源","date":"2026/09/20 10:00","categories":["开源项目"],"tags":["RuoYi","开源项目"],"showArticleMetadata":false},"headers":[],"relativePath":"open-source/01-RuoYi/03-启动链路.md","filePath":"open-source/01-RuoYi/03-启动链路.md","lastUpdated":1789912873000}'),g={name:"open-source/01-RuoYi/03-启动链路.md"},b=i("h1",{id:"启动链路",tabindex:"-1"},[m("启动链路 "),i("a",{class:"header-anchor",href:"#启动链路","aria-label":'Permalink to "启动链路"'},"​")],-1),y=h(`<h2 id="本篇目标" tabindex="-1">本篇目标 <a class="header-anchor" href="#本篇目标" aria-label="Permalink to &quot;本篇目标&quot;">​</a></h2><p>从 Java <code>main</code> 方法跟到 Spring Boot 创建应用上下文并启动 Web 服务，识别启动类、配置文件和自定义基础设施配置各自的作用。这里关注可从源码验证的高层顺序，不把 Spring 内部 Bean 创建细节简化成固定的单一调用链。</p><h2 id="源码入口" tabindex="-1">源码入口 <a class="header-anchor" href="#源码入口" aria-label="Permalink to &quot;源码入口&quot;">​</a></h2><ul><li><a href="https://gitee.com/y_project/RuoYi-Vue" target="_blank" rel="noreferrer">RuoYi-Vue 仓库</a></li><li><a href="https://gitee.com/y_project/RuoYi-Vue/tree/master/ruoyi-admin/src/main/java/com/ruoyi" target="_blank" rel="noreferrer">ruoyi-admin 启动类所在目录</a></li><li><a href="https://gitee.com/y_project/RuoYi-Vue/blob/master/ruoyi-admin/pom.xml" target="_blank" rel="noreferrer">ruoyi-admin 模块 POM</a></li><li><a href="https://gitee.com/y_project/RuoYi-Vue/tree/master/ruoyi-framework/src/main/java/com/ruoyi/framework/config" target="_blank" rel="noreferrer">ruoyi-framework 配置目录</a></li></ul><p>在当前阅读版本中，启动类是 <code>ruoyi-admin/src/main/java/com/ruoyi/RuoYiApplication.java</code>。应用配置位于 <code>ruoyi-admin/src/main/resources</code>，数据源和 MyBatis 等基础配置可从 <code>ruoyi-framework</code> 的配置类继续追踪。</p><h2 id="调用链或模块关系" tabindex="-1">调用链或模块关系 <a class="header-anchor" href="#调用链或模块关系" aria-label="Permalink to &quot;调用链或模块关系&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span>RuoYiApplication.main(args)</span></span>
<span class="line"><span>  → SpringApplication.run(RuoYiApplication.class, args)</span></span>
<span class="line"><span>  → Spring Boot 读取环境与配置、创建应用上下文</span></span>
<span class="line"><span>  → 扫描 com.ruoyi 下的组件并装配各模块中的 Bean</span></span>
<span class="line"><span>  → 加载框架配置与应用配置，准备数据访问等基础设施</span></span>
<span class="line"><span>  → Web 容器启动并对外提供 Controller 定义的接口</span></span></code></pre></div><p>这是便于阅读源码的概览。Spring Boot 会通过自动配置、配置类和依赖条件共同决定实际 Bean 的注册过程，具体执行次序应以当前版本的断点或启动日志为准。</p><h2 id="核心实现" tabindex="-1">核心实现 <a class="header-anchor" href="#核心实现" aria-label="Permalink to &quot;核心实现&quot;">​</a></h2><p><code>RuoYiApplication</code> 使用 <code>@SpringBootApplication</code> 标记应用入口，并在 <code>main</code> 中调用 <code>SpringApplication.run</code>。当前源码显式排除了 Spring Boot 默认的 <code>DataSourceAutoConfiguration</code>；<code>ruoyi-framework</code> 中的 Druid 配置根据应用属性创建数据源，再由 MyBatis 配置注册持久层相关 Bean。这样读启动问题时，可以把“应用入口”和“基础设施具体实现”分开检查。</p><p>启动类位于 <code>com.ruoyi</code> 包下，组件扫描范围会覆盖该包下的子包。模块代码是否会被装配，还取决于它是否在应用依赖中，以及其中的组件是否满足配置条件。</p><h2 id="我的理解" tabindex="-1">我的理解 <a class="header-anchor" href="#我的理解" aria-label="Permalink to &quot;我的理解&quot;">​</a></h2><p>启动类只负责交给 Spring Boot 启动应用，不直接创建全部业务对象。启动过程的重点是类路径决定可见模块，配置和条件决定注册哪些 Bean，最后 Web 容器接管请求。排查启动问题时，我会先确认报错发生在配置读取、Bean 装配、数据源初始化还是 Web 服务启动阶段。</p><h2 id="可验证实验" tabindex="-1">可验证实验 <a class="header-anchor" href="#可验证实验" aria-label="Permalink to &quot;可验证实验&quot;">​</a></h2><ol><li>在 <code>RuoYiApplication.main</code> 的 <code>SpringApplication.run</code> 行设置断点，观察调用返回前后应用上下文和 Web 服务的状态。</li><li>查看启动类上的排除项，再搜索 <code>DruidConfig</code>、<code>MyBatisConfig</code>，确认数据源与持久层由哪些配置类负责。</li><li>对照 <code>application.yml</code> 和对应环境配置，逐项确认启动所需的数据库、Redis 等外部服务；本地没有准备这些服务时，可先只做静态代码追踪。</li></ol><p>以上目录与调用路径以当前阅读版本为参照；不同 RuoYi 版本、分支或二次开发仓库的具体路径和实现可能不同，请以本地 checkout 为准。</p><h2 id="关联笔记与源码链接" tabindex="-1">关联笔记与源码链接 <a class="header-anchor" href="#关联笔记与源码链接" aria-label="Permalink to &quot;关联笔记与源码链接&quot;">​</a></h2><ul><li><a href="/open-source/01-RuoYi/01-项目概览">项目概览</a></li><li><a href="/open-source/01-RuoYi/02-目录与模块">目录与模块</a></li><li><a href="https://gitee.com/y_project/RuoYi-Vue" target="_blank" rel="noreferrer">RuoYi-Vue 仓库</a> · <a href="https://gitee.com/y_project/RuoYi-Vue/blob/master/ruoyi-admin/pom.xml" target="_blank" rel="noreferrer">ruoyi-admin 模块 POM</a></li></ul>`,18);function k(e,R,Y,B,A,S){const t=c,n=s("ClientOnly");return r(),p("div",null,[b,d(n,null,{default:u(()=>{var a,o;return[(((a=e.$frontmatter)==null?void 0:a.aside)??!0)&&(((o=e.$frontmatter)==null?void 0:o.showArticleMetadata)??!0)?(r(),_(t,{key:0,article:e.$frontmatter},null,8,["article"])):f("",!0)]}),_:1}),y])}const v=l(g,[["render",k]]);export{P as __pageData,v as default};
